ON CONFLICT (month_id, line) DO UPDATE SET label=EXCLUDED.label, amount=EXCLUDED.amount, sort=EXCLUDED.sort, note=EXCLUDED.note, updated_at=now();
UPDATE t_p93118852_lineaschool_initiati.fm_pnl_fact_manual SET note='Таблица заказчика «Факт 2026», ИТОГО месяца: уроки × цена по ученикам + диагностики', updated_at=now() WHERE month_id IN ('2026-01','2026-02') AND line='revenue';
UPDATE t_p93118852_lineaschool_initiati.fm_fact_monthly SET note='Таблица заказчика «Факт 2026» (ИТОГО: уроки + диагностики)' WHERE month_id BETWEEN '2026-01' AND '2026-05';